import{z as n,x as o,o as B,c as p,q as r,j as l,D as A,d as a,s as t,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"开源协作与上游回馈","description":"","frontmatter":{"title":"开源协作与上游回馈","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rw-open-source-upstream.md","filePath":"llm/rw-open-source-upstream.md","lastUpdated":1791413859000}'),d={name:"llm/rw-open-source-upstream.md"};function u(m,E,C,D,c,h){const s=o("Mermaid");return B(),p("div",null,[E[2]||(E[2]=r('<h1 id="开源协作与上游回馈" tabindex="-1">开源协作与上游回馈 <a class="header-anchor" href="#开源协作与上游回馈" aria-label="Permalink to &quot;开源协作与上游回馈&quot;">​</a></h1><div class="epigraph"><p>给了足够的眼睛，所有 bug 都现形——但前提是你的发现让那些眼睛看得见。</p><footer>—— Linus 定律，据 Raymond, The Cathedral and the Bazaar, 1999 整理</footer></div><p><a href="/llm/rw-baseline-alignment">上一课</a>的判定落定后，复现的副产品开始堆积：修好的 bug、补齐的文档、澄清的配置、可复算的脚本。这些资产留在你的硬盘里，价值随时间衰减；送回上游，价值随每个后来者增长。开源生态课已经讲过发布侧的规范——许可证谱系见<a href="/llm/eco-license-spectrum">许可证谱系与选择</a>；本课写复现者的回馈路径：从一条好 issue 到一个被合并的修复，回馈如何反过来成为复现工作流的闭环。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>复现者的回馈有三个典型失败。其一，沉默：发现上游 bug 与披露缺口，只在内部笔记里记档——下一个人在同一处再摔一次，上游永远不知道。其二，噪音：把不完整的观察丢进 issue——「我跑不通」，没有版本、没有最小复现、没有期望与实际，维护者只能关闭。其三，越界：复现分叉里顺手重构了上游代码，diff 无法审，回馈不成反而树敌。三者的共同缺口是把「我的复现发现」翻译成「维护者可以行动的动作」。</p><p><span class="marginnote">「最小复现」就是把 bug 剥到只剩骨架的几十行独立脚本：删掉一切与 bug 无关的代码后仍能触发问题。它既是给维护者的路标，也是你自己排错的起点——很多 bug 在剥离的过程中就自己现形了。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>回馈按表面积由小到大四级，逐级升级。第一级，好 issue：三要素齐全——最小复现（最小到几十行的独立脚本）、环境坐标（版本、硬件、锁文件哈希）、期望与实际的精确对照；最小复现脚本本质上就是第一课「结果复现」的微型化，你在复现工作流里练的正是这件事。第二级，文档 PR：把你走读时补的入口说明、环境坑、决策表里显式化的隐性约定写成文档改动——影响面小、审查快，是建立信誉的入口。第三级，修复 PR：一条提交只做一件事，与仓库现有测试风格对齐，先跑通本地 CI；大改先开讨论贴，让维护者在代码之前同意方向。第四级，复现包独立发布：与原项目名字区分、许可证兼容、数据与模型权重按其许可条款分发。</p><p><span class="marginnote">四级回馈像去别人家帮忙：issue 是指出哪扇门坏了（不动手）；文档 PR 是把门牌写清楚（改一张纸）；修复 PR 是换合页（动一个零件）；独立复现包是照人家的图纸另盖了间工具房（独立建筑，须另立门户）。动静越大，越要先征得主人同意。</span></p>',9)),(B(),l(i,null,{default:A(()=>[t(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20FIND%5B%22%E5%A4%8D%E7%8E%B0%E5%8F%91%E7%8E%B0%22%5D%20--%3E%20T%7B%22%E6%80%A7%E8%B4%A8%E5%88%A4%E5%AE%9A%22%7D%0A%20%20T%20--%3E%7C%22%E4%B8%8A%E6%B8%B8%E7%BC%BA%E9%99%B7%22%7C%20ISS%5B%22%E5%A5%BD%20issue%EF%BC%9A%E5%A4%8D%E7%8E%B0%2B%E5%9D%90%E6%A0%87%2B%E5%AF%B9%E7%85%A7%22%5D%0A%20%20T%20--%3E%7C%22%E6%96%87%E6%A1%A3%E7%BC%BA%E5%8F%A3%22%7C%20DOC%5B%22%E6%96%87%E6%A1%A3%20PR%22%5D%0A%20%20T%20--%3E%7C%22%E5%8F%AF%E4%BF%AE%22%7C%20FIX%5B%22%E4%BF%AE%E5%A4%8D%20PR%EF%BC%9A%E4%B8%80%E4%BA%8B%E4%B8%80%E6%8F%90%E4%BA%A4%22%5D%0A%20%20T%20--%3E%7C%22%E9%85%8D%E6%96%B9%E7%BA%A7%22%7C%20PKG%5B%22%E7%8B%AC%E7%AB%8B%E5%A4%8D%E7%8E%B0%E5%8C%85%EF%BC%9A%E6%94%B9%E5%90%8D%2B%E5%90%88%E8%A7%84%22%5D%0A%20%20ISS%20--%3E%20UP%5B%22%E4%B8%8A%E6%B8%B8%E5%90%88%E5%B9%B6%E6%88%96%E5%85%B3%E9%97%AD%22%5D%0A%20%20DOC%20--%3E%20UP%0A%20%20FIX%20--%3E%20UP%0A%20%20UP%20--%3E%20NEXT%5B%22%E4%B8%8B%E4%B8%80%E4%B8%AA%E5%A4%8D%E7%8E%B0%E8%80%85%E7%9A%84%E8%B5%B7%E7%82%B9%E6%8A%AC%E9%AB%98%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("为什么回馈是复现工作流的闭环而不是慈善：你的修复被合并后，上游的下一步使用者从你的终点出发，同领域的复现基线整体抬升；你的 issue 里那几十行最小复现脚本，是整个社区共用的归因捷径。复现者在这条链上有独特优势——你被迫做过单步对账、环境冻结与死因归档，这些恰好是好 issue 的全部原料；回馈的边际成本因此比一般用户低得多。贡献流程的细节（分支约定、CI 门槛、审阅礼仪）见"),e("a",{href:"/llm/fw-contribution-map"},"贡献流程与收束"),a("，本课不重复。")],-1)),E[5]||(E[5]=e("p",null,"维护者视角决定可合并性：一个 change 的合并概率取决于它的表面积（动了多少接口）与测试覆盖，不取决于你发现的问题多重要。所以「重要但大」的发现要拆：先发 issue 固定事实，再把可独立合并的最小修复逐个送出。",-1)),(B(),l(i,null,{default:A(()=>[t(s,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E4%B8%80%E4%B8%AA%E5%80%99%E9%80%89%20change%22%5D%20--%3E%20Q%7B%22%E8%A1%A8%E9%9D%A2%E7%A7%AF%E5%A4%9A%E5%A4%A7%22%7D%0A%20%20Q%20--%3E%7C%22%E5%B0%8F%EF%BC%9A%E5%8D%95%E6%8E%A5%E5%8F%A3%E5%8D%95%E8%A1%8C%E4%B8%BA%22%7C%20T%5B%22%E8%A1%A5%E6%B5%8B%E8%AF%95%EF%BC%8C%E7%9B%B4%E6%8E%A5%E5%8F%91%20PR%22%5D%0A%20%20Q%20--%3E%7C%22%E5%A4%A7%EF%BC%9A%E8%B7%A8%E5%A4%9A%E4%B8%AA%E6%A8%A1%E5%9D%97%22%7C%20S%5B%22%E6%8B%86%E6%88%90%E5%8F%AF%E7%8B%AC%E7%AB%8B%E5%90%88%E5%B9%B6%E7%9A%84%E6%9C%80%E5%B0%8F%E5%BA%8F%E5%88%97%22%5D%0A%20%20S%20--%3E%20I%5B%22%E5%85%88%E5%8F%91%20issue%EF%BC%9A%E5%9B%BA%E5%AE%9A%E4%BA%8B%E5%AE%9E%E4%B8%8E%E6%96%B9%E5%90%91%22%5D%0A%20%20I%20--%3E%20P1%5B%22PR%20%E4%B8%80%EF%BC%9A%E6%9C%80%E5%B0%8F%E4%BF%AE%E5%A4%8D%22%5D%0A%20%20I%20--%3E%20P2%5B%22PR%20%E4%BA%8C%EF%BC%9A%E6%96%87%E6%A1%A3%E4%B8%8E%E6%B5%8B%E8%AF%95%22%5D%0A%20%20T%20--%3E%20M%5B%22%E5%90%88%E5%B9%B6%E6%A6%82%E7%8E%87%E9%AB%98%22%5D%0A%20%20P1%20--%3E%20M%0A%20%20P2%20--%3E%20M%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=r('<p><span class="marginnote">常见误区：以为问题越重大、diff 越彻底，越容易被合并。维护者的审阅预算有限：一个动 30 个文件的大 PR 要对方免费投入好几天，多半被搁置；10 行的单点修复当天就能进。把大发现拆成小步不是妥协，是策略。</span></p><p><span class="marginnote">把复现能力变成别人的一键命令，是性价比最高的回馈：docker 镜像或一条复现脚本加固定种子，让任何人分钟级重放你的关键判定表。审稿、评审与内部决策引用的将是这个命令，而不是你论文里的一行数字。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>回馈有合规边界：私有数据、内部评测集、许可受限的权重不出门；第三方复现的发布不得使用原项目名称背书，报告里的对比遵守上游的引用要求。回馈有信用边界：复现中发现的原文问题向上游提出时用中性措辞——「报告与仓库在 X 处不一致，最小示例如下」，不做有罪推定；复现社区的长期货币是克制。回馈也有范围边界：大规模实验的完整日志不进 issue，压缩成决策可用的形式；你的分叉与上游的漂移要记账——每季度对一次上游 release，漂移大了就写明分叉的定位是「复现档案」而不是「可用分支」，不诱导下游依赖。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>回馈四级按表面积升序：好 issue、文档 PR、修复 PR、独立复现包；逐级升级不越级。</li><li>好 issue 三要素：最小复现、环境坐标、期望与实际对照；它就是微型结果复现。</li><li>可合并性由 change 的表面积与测试覆盖决定；大发现拆小步送出。</li><li>合规与措辞边界：受限资产不出门，对原文问题做中性陈述。</li><li>出处：Raymond, 1999；流程细节见<a href="/llm/fw-contribution-map">贡献流程与收束</a>，许可口径见<a href="/llm/eco-license-spectrum">许可证谱系与选择</a>。</li></ul>',6))])}const P=n(d,[["render",u]]);export{F as __pageData,P as default};
